pageshot index.html && python - <<'PY'
import json,pandas as pd,numpy as np
facts=json.load(open('facts.json'))
for f in facts:
    env={'pd':pd,'np':np}
    for name,path in f['tables'].items(): env[name]=pd.read_csv(path)
    value=eval(f['code'],env)
    print('\n'+f['id']+'\n'+str(value))
print('\nAll',len(facts),'facts evaluated successfully.')
PY
